#include "gfx/gs_resources.h"#include "gfx/gl_context.h"#include "gfx/gl/GlGfx.h"#include "gfx/bt3gl_api.h"   // [B] bt3* API bridgenamespace ps2x::gfx{    // ------------------------------------------------------------------------------ GsTexture    bool GsTexture::Create(int w, int h, const void *rgba)    {        if (!gl::ContextReady() || w <= 0 || h <= 0) return false;        auto *t = new gl::Texture();        if (!t->Create(gl::Device(), (uint32_t)w, (uint32_t)h, gl::Format::RGBA8, rgba))        { delete t; return false; }        impl = t; id = t->GLTexture(); width = w; height = h;        return true;    }    void GsTexture::Update(const void *rgba, int pitchBytes)    {        (void)pitchBytes;        if (!impl || !rgba) return;        static_cast<gl::Texture *>(impl)->Update(gl::Device(), rgba);    }    void GsTexture::SetFilter(bool linear)    {        if (!impl) return;        static_cast<gl::Texture *>(impl)->SetSampler(gl::Device(), linear ? gl::Filter::Linear : gl::Filter::Point,                                                     gl::Wrap::Clamp);    }    void GsTexture::SetWrap(bool repeat)    {        if (!impl) return;        static_cast<gl::Texture *>(impl)->SetSampler(gl::Device(), gl::Filter::Point,                                                     repeat ? gl::Wrap::Repeat : gl::Wrap::Clamp);    }    void GsTexture::Unload()    {        if (impl) { static_cast<gl::Texture *>(impl)->Destroy(); delete static_cast<gl::Texture *>(impl); impl = nullptr; }        id = 0; width = height = 0;    }    // -------------------------------------------------------------------------- GsRenderTarget    bool GsRenderTarget::Create(int w, int h, bool depth)    {        if (!gl::ContextReady() || w <= 0 || h <= 0) return false;        auto *rt = new gl::RenderTarget();        if (!rt->Create(gl::Device(), (uint32_t)w, (uint32_t)h, depth))        { delete rt; return false; }        impl = rt; width = w; height = h;        id = rt->GLFramebuffer();        texture.id = rt->Color().GLTexture();        texture.width = w; texture.height = h;        texture.impl = nullptr;   // the colour texture is owned by the RenderTarget, not GsTexture        return true;    }    void GsRenderTarget::Begin()    {        // A1: raylib's bt3BeginTextureMode also flushes the rlgl batch before switching targets.        bt3rlDrawRenderBatchActive();        bt3rlEnableFramebuffer(id);        bt3rlViewport(0, 0, width, height);    }    void GsRenderTarget::End()    {        bt3rlDrawRenderBatchActive();        bt3rlEnableFramebuffer(0);        bt3rlViewport(0, 0, bt3GetScreenWidth(), bt3GetScreenHeight());    }    void GsRenderTarget::Unload()    {        if (impl) { static_cast<gl::RenderTarget *>(impl)->Destroy(); delete static_cast<gl::RenderTarget *>(impl); impl = nullptr; }        id = 0; texture.id = 0; texture.width = texture.height = 0; width = height = 0;    }}